BEGIN;
DO $test$
DECLARE pr uuid:=gen_random_uuid(); lo uuid:=gen_random_uuid(); pe uuid:=gen_random_uuid(); st uuid; ex uuid; r jsonb; d date:=(now() AT TIME ZONE 'America/New_York')::date-1; start_at timestamptz; end_at timestamptz;
BEGIN
INSERT INTO projects(id,name,customer_id,start_date,day_shift_start,day_shift_end,night_shift_start,early_window_minutes) SELECT pr,'__punch_rollback_test',customer_id,d,'07:30','18:00','19:30',30 FROM projects LIMIT 1;
INSERT INTO project_locations(id,project_id,name,timezone,day_shift_start,day_shift_end,night_shift_start) VALUES(lo,pr,'__punch_rollback_test','America/New_York','07:30','18:00','19:30');
INSERT INTO personnel(id,personnel_number,first_name,last_name,email) VALUES(pe,'TEST-'||pe::text,'Rollback','Punch',pe::text||'@example.invalid');
start_at:=(d+time '07:30') AT TIME ZONE 'America/New_York'; end_at:=(d+time '18:00') AT TIME ZONE 'America/New_York';
r:=public._punch_core(lo,pe,NULL,NULL,NULL,NULL,start_at-interval '18 minutes',NULL,NULL);
IF NOT (r->>'ok')::boolean OR (r->>'at')::timestamptz<>start_at THEN RAISE EXCEPTION 'early clamp failed: %',r; END IF;
r:=public._punch_core(lo,pe,NULL,NULL,NULL,NULL,end_at+interval '102 minutes',NULL,NULL);
IF NOT (r->>'ok')::boolean OR (r->>'at')::timestamptz<>end_at THEN RAISE EXCEPTION 'late clamp failed: %',r; END IF;
SELECT vp.id INTO st FROM visit_personnel vp JOIN location_visits lv ON lv.id=vp.visit_id WHERE lv.location_id=lo AND vp.personnel_id=pe;
IF NOT EXISTS(SELECT 1 FROM visit_personnel WHERE id=st AND actual_in_at=start_at-interval '18 minutes' AND actual_out_at=end_at+interval '102 minutes') THEN RAISE EXCEPTION 'actual taps not retained';END IF;
IF NOT EXISTS(SELECT 1 FROM time_entries WHERE visit_personnel_id=st AND clock_in_at=start_at AND clock_out_at=end_at AND hours=10.5) THEN RAISE EXCEPTION 'counted ledger mismatch';END IF;
SELECT id INTO ex FROM shift_extensions WHERE location_id=lo AND personnel_id=pe;
IF ex IS NULL OR NOT EXISTS(SELECT 1 FROM admin_notifications WHERE related_id=ex AND message LIKE '%19:42%18:00%') THEN RAISE EXCEPTION 'approval notification missing';END IF;
UPDATE shift_extensions SET status='approved',decided_at=now() WHERE id=ex;
IF NOT EXISTS(SELECT 1 FROM visit_personnel WHERE id=st AND checked_out_at=end_at+interval '90 minutes') THEN RAISE EXCEPTION 'approved actual not rounded to 1930';END IF;
IF NOT EXISTS(SELECT 1 FROM time_entries WHERE visit_personnel_id=st AND hours=12) THEN RAISE EXCEPTION 'approved ledger mismatch';END IF;
UPDATE shift_extensions SET status='denied',decided_at=now() WHERE id=ex;
IF NOT EXISTS(SELECT 1 FROM visit_personnel WHERE id=st AND checked_out_at=end_at) THEN RAISE EXCEPTION 'denial must retain schedule';END IF;
UPDATE visit_personnel SET manual_time_override=true,checked_in_at=start_at-interval '30 minutes',checked_out_at=end_at+interval '2 hours' WHERE id=st;
UPDATE shift_extensions SET status='approved',decided_at=now() WHERE id=ex;
IF NOT EXISTS(SELECT 1 FROM visit_personnel WHERE id=st AND checked_in_at=start_at-interval '30 minutes' AND checked_out_at=end_at+interval '2 hours') THEN RAISE EXCEPTION 'manual edits clamped';END IF;
INSERT INTO personnel(id,personnel_number,first_name,last_name,email) VALUES(gen_random_uuid(),'TEST2-'||pe::text,'Early','Approval',gen_random_uuid()::text||'@example.invalid') RETURNING id INTO pe;
r:=public._punch_core(lo,pe,NULL,NULL,NULL,NULL,start_at-interval '45 minutes',NULL,NULL);
IF r->>'reason'<>'before_shift' THEN RAISE EXCEPTION 'beyond-window reason lost';END IF;
r:=public._punch_core(lo,pe,NULL,NULL,NULL,NULL,start_at-interval '45 minutes','Prep work',NULL);
IF (r->>'at')::timestamptz<>start_at THEN RAISE EXCEPTION 'unapproved early reason counts actual';END IF;
SELECT vp.id INTO st FROM visit_personnel vp JOIN location_visits lv ON lv.id=vp.visit_id WHERE lv.location_id=lo AND vp.personnel_id=pe;
UPDATE visit_personnel SET offsite_approved_at=now() WHERE id=st;
IF NOT EXISTS(SELECT 1 FROM visit_personnel WHERE id=st AND checked_in_at=start_at-interval '45 minutes' AND actual_in_at=start_at-interval '45 minutes') THEN RAISE EXCEPTION 'early approval did not recount';END IF;
END $test$;
ROLLBACK;
